using UnityEngine;

namespace Astrea;

public class ParticleFollower : MonoBehaviour
{
	private const float orthoToPerspectiveAdjustment = 1.06f;

	private const float orthoToPerspectiveDiceRotatedYAdjustment = 0.15f;

	private const float orthoToPerspectiveDiceRotatedYAdjustmentSentinelEnemy = 0.06f;

	private const float orthoToPerspectiveZAdjustment = 0.024f;

	private DiceInstance diceInstance;

	private bool stopFollowing;

	private float yAdjustment;

	public void Initialize(DiceInstance diceInstance)
	{
		this.diceInstance = diceInstance;
		stopFollowing = false;
		yAdjustment = ((diceInstance.DiceOwnerEnum == DiceOwnerEnum.PLAYER) ? 0.15f : 0.06f);
	}

	private void Update()
	{
		if (!stopFollowing)
		{
			Vector3 position = diceInstance.transform.position;
			Vector3 vector = position.ZeroZ() * 1.06f;
			float num = Mathf.Abs(position.z) * 0.024f;
			base.transform.position = (vector + Vector3.up * yAdjustment) * (num + 1f);
		}
		else
		{
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
		}
		if (diceInstance.Discarding || !diceInstance.gameObject.activeInHierarchy)
		{
			stopFollowing = true;
		}
	}
}
